try {
    var data = JSON.parse(msg.payload);
    if (!data.msg || !data.msg.name || !data.msg.position) return null;

    var names = data.msg.name;
    var positions = data.msg.position;

    var ur5Joints = [
        'ur5_shoulder_pan_joint',
        'ur5_shoulder_lift_joint',
        'ur5_elbow_joint',
        'ur5_wrist_1_joint',
        'ur5_wrist_2_joint',
        'ur5_wrist_3_joint'
    ];

    var result = {};
    for (var i = 0; i < names.length; i++) {
        if (ur5Joints.includes(names[i])) {
            result[names[i]] = parseFloat(positions[i]);
        }
    }

    var ur5Positions = ur5Joints.map(function(jn) { return result[jn] || 0.0; });
    flow.set('feedback_positions', ur5Positions);

    var display = '';
    var sliders = [null, null, null, null, null, null];
    var degLabels = [null, null, null, null, null, null];
    var shouldSync = flow.get('sync_sliders_now');

    ur5Joints.forEach(function(jn, idx) {
        var shortName = ['J1','J2','J3','J4','J5','J6'][idx];
        var val = result[jn] || 0.0;
        var deg = parseFloat((val * 180 / Math.PI).toFixed(1));
        display += shortName + ': ' + val.toFixed(4) + ' rad\n';

        // always update degree labels
        degLabels[idx] = {payload: deg};

        if (shouldSync) {
            sliders[idx] = {payload: deg};
            flow.set('j'+(idx+1), val);
        }
    });

    if (shouldSync) {
        flow.set('joint_values', ur5Joints.map(function(jn){ return result[jn]||0; }));
        flow.set('sync_sliders_now', false);
    }

    msg.payload = display.trim();
    return [msg,
            sliders[0], sliders[1], sliders[2], sliders[3], sliders[4], sliders[5],
            degLabels[0], degLabels[1], degLabels[2], degLabels[3], degLabels[4], degLabels[5]];

} catch(e) {
    return null;
}

var dur = parseFloat(msg.payload) || 2.0;
flow.set('joint_duration', dur);
return msg;

var dur = flow.get('joint_duration') || 2.0;
msg.payload = {joint: 0, angle_deg: parseFloat(msg.payload), duration_sec: dur};
return msg;

var dur = flow.get('joint_duration') || 2.0;
msg.payload = {joint: 1, angle_deg: parseFloat(msg.payload), duration_sec: dur};
return msg;

var dur = flow.get('joint_duration') || 2.0;
msg.payload = {joint: 2, angle_deg: parseFloat(msg.payload), duration_sec: dur};
return msg;

var dur = flow.get('joint_duration') || 2.0;
msg.payload = {joint: 3, angle_deg: parseFloat(msg.payload), duration_sec: dur};
return msg;

var dur = flow.get('joint_duration') || 2.0;
msg.payload = {joint: 4, angle_deg: parseFloat(msg.payload), duration_sec: dur};
return msg;

var dur = flow.get('joint_duration') || 2.0;
msg.payload = {joint: 5, angle_deg: parseFloat(msg.payload), duration_sec: dur};
return msg;

var mode = msg.payload.mode;
if (mode === 'LOCKED') {
    msg.payload = 'LOCKED';
} else if (mode === 'MANUAL') {
    msg.payload = 'READY';
} else {
    msg.payload = '...';
}
return msg;
